import { useEffect, useState, useContext } from "react";
import api from "../api";
import { AuthContext } from "../context/AuthContext";

export default function AdminDashboard() {
  const { logout } = useContext(AuthContext);

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);

  // Fetch initial data
  useEffect(() => {
    fetchVotingStatus();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  const fetchVotingStatus = async () => {
    try {
      const res = await api.get("/admin/toggle-voting"); // we can add a GET route if needed
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      fetchLogs();
    } catch (err) {
      console.error(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
      fetchLogs();
    } catch (err) {
      console.error(err);
    }
  };

  const deleteCandidate = async (id) => {
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
      fetchLogs();
    } catch (err) {
      console.error(err);
    }
  };

  const generateReport = async () => {
    try {
      await api.post("/admin/generate-report");
      fetchLogs();
      alert("Report generated ✅");
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="p-8 bg-gray-50 min-h-screen">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">iVote Admin Dashboard</h1>
        <button
          onClick={logout}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          Logout
        </button>
      </div>

      {/* Voting Status */}
      <div className="mb-6">
        <h2 className="font-semibold text-lg">Voting Status</h2>
        <p>Current Status: {votingOpen ? "Open" : "Closed"}</p>
        <button
          onClick={toggleVoting}
          className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </div>

      {/* Pending Users */}
      <div className="mb-6">
        <h2 className="font-semibold text-lg">Pending Voter Registrations</h2>
        {pendingUsers.length === 0 ? (
          <p>No pending users.</p>
        ) : (
          pendingUsers.map((user) => (
            <div
              key={user.id}
              className="flex justify-between items-center py-1"
            >
              <span>{user.name} ({user.email})</span>
              <button
                onClick={() => approveUser(user.id)}
                className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
              >
                Approve
              </button>
            </div>
          ))
        )}
      </div>

      {/* Candidates */}
      <div className="mb-6">
        <h2 className="font-semibold text-lg">Candidates</h2>
        {candidates.length === 0 ? (
          <p>No candidates yet.</p>
        ) : (
          <table className="w-full text-left border-collapse">
            <thead>
              <tr>
                <th className="border-b py-2">Name</th>
                <th className="border-b py-2">Position</th>
                <th className="border-b py-2">Party</th>
                <th className="border-b py-2">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((c) => (
                <tr key={c.id}>
                  <td className="py-1">{c.name}</td>
                  <td className="py-1">{c.position}</td>
                  <td className="py-1">{c.party || "-"}</td>
                  <td className="py-1 space-x-2">
                    {/* Implement edit modal if needed */}
                    <button
                      onClick={() => deleteCandidate(c.id)}
                      className="bg-red-600 text-white px-2 py-1 rounded hover:bg-red-700"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* System Logs */}
      <div className="mb-6">
        <h2 className="font-semibold text-lg">System Logs</h2>
        {logs.length === 0 ? (
          <p>No logs available.</p>
        ) : (
          <ul className="list-disc ml-6 max-h-48 overflow-y-auto">
            {logs.map((log) => (
              <li key={log.id}>
                [{new Date(log.createdAt).toLocaleString()}] {log.action}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Generate Report */}
      <div className="mb-6">
        <button
          onClick={generateReport}
          className="bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-700"
        >
          Generate Final Report
        </button>
      </div>
    </div>
  );
}
